package com.example.Kcsj.erp;

import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.beans.factory.annotation.Value;
import com.fasterxml.jackson.databind.ObjectMapper;
import javax.servlet.http.HttpServletRequest;
import java.time.Instant;
import java.nio.file.*;
import java.util.*;
import static com.example.Kcsj.erp.ErpStore.*;
import static com.example.Kcsj.erp.AccountGovernanceController.*;

/** Retention is a two-person operation. The administrator sees metadata, never record bodies. */
@RestController
public class RetentionController {
    private final ErpStore store;private final AuthService auth;private final BusinessService business;private final ObjectMapper json;private final BackupService backups;
    @Value("${erp.upload-dir}")private String uploadDirectory;
    private static final Set<String>KINDS=new HashSet<>(Arrays.asList("file","collection_export","student_import","college_import","account_import","operation","account_invite","request","worklog","collection"));
    public RetentionController(ErpStore store,AuthService auth,BusinessService business,ObjectMapper json,BackupService backups){this.store=store;this.auth=auth;this.business=business;this.json=json;this.backups=backups;}
    private Map<String,Object>ok(Object v){return map("code",0,"data",v);}
    private Map<String,Object>admin(HttpServletRequest request){Map<String,Object>a=auth.require(request);auth.writeAllowed(a);auth.admin(a);return a;}
    @GetMapping("/retention")public Map<String,Object>list(HttpServletRequest request){Map<String,Object>a=auth.require(request);auth.admin(a);return ok(map("policies",store.all("retention_policy"),"reviews",store.all("retention_review"),"tombstones",store.all("deletion_tombstone")));}
    @PostMapping("/retention/policies")@Transactional public Map<String,Object>policy(@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=admin(request);String kind=business.text(body,"kind",32,true);if(!KINDS.contains(kind))throw new ApiException(400,"该类型尚未接入安全留存处置，禁止直接删除");int days;try{days=Integer.parseInt(s(body,"days"));}catch(Exception e){throw new ApiException(400,"保留天数必须为整数");}if(days<1||days>36500)throw new ApiException(400,"保留期限为1至36500天");String effective=business.date(body,"effectiveAt");if(effective.isEmpty())throw new ApiException(400,"生效时间必填");Map<String,Object>p=map("id",id(),"kind",kind,"days",days,"effectiveAt",effective,"basis",business.text(body,"basis",2000,true),"reason",business.text(body,"reason",1000,true),"authorId",s(a,"id"),"status","pending","version",store.all("retention_policy").stream().filter(v->s(v,"kind").equals(kind)).count()+1,"createdAt",now());store.save("retention_policy",p);auth.audit(a,"retention.policy_request","留存策略编号 "+s(p,"id"));return ok(p);}
    @PostMapping("/retention/policies/{id}/approve")@Transactional public Map<String,Object>approvePolicy(@PathVariable String id,@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=admin(request),p=store.get("retention_policy",id);if(s(p,"authorId").equals(s(a,"id")))throw new ApiException(403,"留存策略不可自审");if(!s(p,"status").equals("pending"))throw new ApiException(409,"策略已处理");p.put("status",b(body,"approved")?"approved":"rejected");p.put("reviewerId",s(a,"id"));p.put("reviewReason",business.text(body,"reason",1000,true));p.put("reviewedAt",now());store.save("retention_policy",p);auth.audit(a,"retention.policy_review","留存策略编号 "+id);return ok(p);}
    @PostMapping("/retention/preview")@Transactional public Map<String,Object>preview(@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=admin(request),p=usablePolicy(business.text(body,"policyId",80,true));String kind=s(p,"kind");List<Map<String,Object>>eligible=new ArrayList<>(),blocked=new ArrayList<>();for(Map<String,Object>r:store.all(kind)){String reason=ineligible(kind,r,p);Map<String,Object>meta=map("kind",kind,"recordId",s(r,"id"),"createdAt",s(r,"createdAt"),"state",s(r,"status"),"reason",reason);if(reason.isEmpty()){meta.put("digest",digest(r));eligible.add(meta);}else blocked.add(meta);}Map<String,Object>review=map("id",id(),"policyId",s(p,"id"),"requesterId",s(a,"id"),"reason",business.text(body,"reason",1000,true),"status","pending","items",eligible,"blocked",blocked,"createdAt",now(),"expiresAt",Instant.now().plusSeconds(86400).toString());store.save("retention_review",review);auth.audit(a,"retention.preview","留存复核编号 "+s(review,"id")+"；可处置 "+eligible.size()+" 条");return ok(review);}
    @PostMapping("/retention/reviews/{id}/approve")@Transactional public Map<String,Object>approve(@PathVariable String id,@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=admin(request),r=store.get("retention_review",id);if(s(r,"requesterId").equals(s(a,"id")))throw new ApiException(403,"删除复核不可由申请人完成");if(!s(r,"status").equals("pending")||auth.expired(s(r,"expiresAt")))throw new ApiException(409,"申请已处理或过期");r.put("status",b(body,"approved")?"approved":"rejected");r.put("reviewerId",s(a,"id"));r.put("reviewReason",business.text(body,"reason",1000,true));r.put("reviewedAt",now());store.save("retention_review",r);auth.audit(a,"retention.review","留存复核编号 "+id);return ok(r);}
    @PostMapping("/retention/reviews/{id}/execute")@Transactional public Map<String,Object>execute(@PathVariable String id,HttpServletRequest request){Map<String,Object>a=admin(request),review=store.get("retention_review",id);if(!s(review,"requesterId").equals(s(a,"id")))throw new ApiException(403,"仅原申请管理员可执行获批处置");if(s(review,"status").equals("executed"))return ok(review);if(!s(review,"status").equals("approved")||s(review,"reviewerId").equals(s(a,"id"))||auth.expired(s(review,"expiresAt")))throw new ApiException(409,"需取得有效的另一管理员复核");Map<String,Object>policy=usablePolicy(s(review,"policyId"));if(!backups.configured()&&Arrays.asList("file","request","worklog","collection").contains(s(policy,"kind")))throw new ApiException(409,"正式资料处置前必须配置加密治理备份密钥，确保恢复时删除记录不会复活");for(Map<String,Object>item:records(review,"items")){Map<String,Object>record=store.get(s(item,"kind"),s(item,"recordId"));if(!s(item,"digest").equals(digest(record))||!ineligible(s(item,"kind"),record,policy).isEmpty())throw new ApiException(409,"预检后数据、引用或期限已变化，请重新预检");}List<String>deletedIds=new ArrayList<>();for(Map<String,Object>item:records(review,"items")){String kind=s(item,"kind"),recordId=s(item,"recordId");Map<String,Object>r=store.get(kind,recordId);if(kind.equals("collection")){for(Map<String,Object>answer:store.all("collection_answer"))if(s(answer,"collectionId").equals(recordId)){tombstone(a,review,policy,"collection_answer",answer);deletedIds.add(s(answer,"id"));}}tombstone(a,review,policy,kind,r);deletedIds.add(recordId);}for(Map<String,Object>cache:store.all("operation")){String response=s(cache,"response");if(deletedIds.stream().anyMatch(response::contains))tombstone(a,review,policy,"operation",cache);}for(Map<String,Object>cache:store.all("collection_export"))if(deletedIds.contains(s(cache,"collectionId")))tombstone(a,review,policy,"collection_export",cache);if(backups.configured())try{review.put("governanceLedger",backups.ledger());}catch(Exception failure){throw new ApiException(409,"治理清单保存失败，本次处置已回滚，请核验备份配置");}review.put("status","executed");review.put("executedAt",now());review.put("deletedCount",deletedIds.size());store.save("retention_review",review);auth.audit(a,"retention.execute","已按双审记录执行 "+id+"；处置 "+deletedIds.size()+" 条；物理附件等待清除核验");return ok(review);}
    private Map<String,Object>usablePolicy(String id){Map<String,Object>p=store.get("retention_policy",id);if(!s(p,"status").equals("approved")||Instant.parse(s(p,"effectiveAt")).isAfter(Instant.now()))throw new ApiException(409,"留存策略尚未复核通过或未到生效时间");return p;}
    private String ineligible(String kind,Map<String,Object>r,Map<String,Object>policy){String time=s(r,"createdAt");boolean formal=Arrays.asList("request","worklog","collection").contains(kind);if(formal){if(!Arrays.asList("closed","cancelled","archived","completed").contains(s(r,"status")))return "业务尚未终结";time=s(r,"archivedAt");if(time.isEmpty())time=s(r,"closedAt");if(time.isEmpty())time=s(r,"completedAt");if(time.isEmpty())return "缺少可信归档时间，需人工核验后补充";}if(time.isEmpty())return "缺少可信创建时间";try{if(Instant.parse(time).plusSeconds(((Number)policy.get("days")).longValue()*86400).isAfter(Instant.now()))return "未到政策保留期限";if(!s(r,"expiresAt").isEmpty()&&!auth.expired(s(r,"expiresAt")))return "尚未超过业务有效期";}catch(Exception e){return "时间字段无效";}if(kind.equals("file")&&referenced(s(r,"id"),Collections.singleton("file")))return "附件仍被正式业务、历史版本或导出引用";if(formal&&referenced(s(r,"id"),new HashSet<>(Arrays.asList(kind,"collection_answer","operation","collection_export","audit","student_history","account_history","retention_review","deletion_tombstone"))))return "存在关联业务或未清理引用，须先核验依赖";return "";}
    private boolean referenced(String id,Set<String>ignore){for(String kind:store.kinds()){if(ignore.contains(kind)||kind.startsWith("retention_")||kind.equals("deletion_tombstone")||kind.equals("audit"))continue;for(Map<String,Object>record:store.all(kind))if(contains(record,id))return true;}return false;}
    private boolean contains(Object value,String id){if(value instanceof Map){for(Object child:((Map<?,?>)value).values())if(contains(child,id))return true;}else if(value instanceof List){for(Object child:(List<?>)value)if(contains(child,id))return true;}else if(value instanceof String)return value.equals(id)||((String)value).contains('"'+id+'"');return false;}
    private String digest(Map<String,Object>r){try{return auth.digest(json.writeValueAsString(r));}catch(Exception e){throw new IllegalStateException(e);}}
    private void tombstone(Map<String,Object>a,Map<String,Object>review,Map<String,Object>policy,String kind,Map<String,Object>r){List<String>names=new ArrayList<>();if(kind.equals("file"))for(String key:Arrays.asList("storedName","previewStoredName","thumbnailStoredName"))if(!s(r,key).isEmpty()&&!names.contains(s(r,key)))names.add(s(r,key));Map<String,Object>t=map("id",id(),"recordKind",kind,"recordId",s(r,"id"),"policyId",s(policy,"id"),"reviewId",s(review,"id"),"deletedAt",now(),"operatorId",s(a,"id"),"reviewerId",s(review,"reviewerId"),"storedNames",names,"recordDigest",digest(r),"filesPurged",names.isEmpty());store.save("deletion_tombstone",t);store.delete(kind,s(r,"id"));}
    @Scheduled(fixedDelay=60000)@Transactional public void purgeFiles(){store.lockWrites();Path root=Paths.get(uploadDirectory).toAbsolutePath().normalize();for(Map<String,Object>t:store.all("deletion_tombstone"))if(!b(t,"filesPurged")){try{for(String name:strings(t,"storedNames",10)){Path p=root.resolve(name).normalize();if(name.contains("/")||name.contains("\\")||!p.startsWith(root)||Files.isSymbolicLink(p))throw new IllegalStateException("Unsafe stored path");Files.deleteIfExists(p);}t.put("filesPurged",true);t.put("filesPurgedAt",now());t.remove("purgeError");}catch(Exception e){t.put("purgeError","物理附件清除失败，等待重试；请运维核验权限与磁盘");}store.save("deletion_tombstone",t);}}
}
